package com.logistics.orderservice.security;
import com.logistics.orderservice.service.JwtService; import io.jsonwebtoken.Claims; import io.jsonwebtoken.JwtException; import io.jsonwebtoken.Jws; import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwtService; public JwtAuthenticationFilter(JwtService jwtService) { this.jwtService=jwtService; } @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain) throws ServletException,IOException { String header=request.getHeader(HttpHeaders.AUTHORIZATION); if(header==null||!header.startsWith("Bearer ")){chain.doFilter(request,response);return;} try { Jws<Claims> parsed=jwtService.parseToken(header.substring(7)); String email=parsed.getPayload().getSubject(); String role=parsed.getPayload().get("role",String.class); if(email==null||email.isBlank()||!("USER".equals(role)||"ADMIN".equals(role))){response.sendError(401,"Invalid token claims");return;} var auth=new UsernamePasswordAuthenticationToken(email,null,List.of(new SimpleGrantedAuthority("ROLE_"+role))); SecurityContextHolder.getContext().setAuthentication(auth); } catch(JwtException|IllegalArgumentException ex){SecurityContextHolder.clearContext();response.sendError(401,"Invalid or expired JWT token");return;} chain.doFilter(request,response); } }
